/**
 * tests/adversarial-ui-m1-stress.js
 * 
 * Empirical Adversarial Stress Test Harness for Milestone UI-M1:
 * - 1920x1080 Canvas Lock & Zero Document Scrollbars
 * - #bgBlur Geometry, Specificity, and Overflow Isolation
 * - .scrolled Dynamic State Transitions (#shade, .app-header, #bgBlur)
 * - Navigation Pill Bar TV-Safe Constraints & Stacking Order
 * - Viewport Resize & Dynamic Element Injection Stress
 */

const { spawn } = require('child_process');
const http = require('http');
const path = require('path');
const fs = require('fs');

const C = {
  reset: '\x1b[0m',
  bold: '\x1b[1m',
  green: '\x1b[32m',
  red: '\x1b[31m',
  yellow: '\x1b[33m',
  cyan: '\x1b[36m',
  magenta: '\x1b[35m',
  gray: '\x1b[90m',
};

let totalTests = 0;
let passedTests = 0;
let failedTests = 0;
const failureDetails = [];

function assert(condition, message, details = {}) {
  totalTests++;
  if (!condition) {
    failedTests++;
    failureDetails.push({ message, details });
    console.log(`  ${C.red}✗ FAIL:${C.reset} ${message}`);
    if (Object.keys(details).length > 0) {
      console.log(`    ${C.gray}Details: ${JSON.stringify(details)}${C.reset}`);
    }
  } else {
    passedTests++;
    console.log(`  ${C.green}✓ PASS:${C.reset} ${message}`);
  }
}

async function run() {
  console.log(`\n${C.bold}${C.cyan}===============================================================${C.reset}`);
  console.log(`${C.bold}${C.cyan}   Cinejoy webOS - UI-M1 Adversarial Layout & Scrim Stress Suite ${C.reset}`);
  console.log(`${C.bold}${C.cyan}===============================================================${C.reset}\n`);

  const appHtmlPath = path.resolve(__dirname, '../app/index.html');
  const appFileUrl = `file://${appHtmlPath}`;
  const cdpPort = 9345;
  const userDataDir = `/tmp/chrome-ui-m1-adversarial-${Date.now()}`;

  const chrome = spawn('google-chrome-stable', [
    '--headless=new',
    `--remote-debugging-port=${cdpPort}`,
    `--user-data-dir=${userDataDir}`,
    '--no-sandbox',
    '--disable-gpu',
    '--window-size=1920,1080',
    '--force-device-scale-factor=1',
    appFileUrl
  ]);

  const cleanup = () => {
    try { chrome.kill('SIGKILL'); } catch (e) {}
    try { fs.rmSync(userDataDir, { recursive: true, force: true }); } catch (e) {}
  };
  process.on('exit', cleanup);
  process.on('SIGINT', () => { cleanup(); process.exit(1); });

  let listRes = null;
  for (let attempt = 0; attempt < 25; attempt++) {
    await new Promise(r => setTimeout(r, 200));
    try {
      listRes = await new Promise((resolve, reject) => {
        http.get(`http://127.0.0.1:${cdpPort}/json/list`, (res) => {
          let data = '';
          res.on('data', chunk => data += chunk);
          res.on('end', () => {
            try { resolve(JSON.parse(data)); } catch (e) { reject(e); }
          });
        }).on('error', reject);
      });
      if (listRes && listRes.length > 0) break;
    } catch (e) {}
  }

  if (!listRes) throw new Error('Headless Chromium CDP connection failed');
  const pageTarget = listRes.find(t => t.url.includes('cinejoy-webos')) || listRes[0];
  const ws = new WebSocket(pageTarget.webSocketDebuggerUrl);
  await new Promise(r => ws.onopen = r);

  let msgId = 1;
  function sendCdp(method, params = {}) {
    return new Promise((resolve, reject) => {
      const id = msgId++;
      const handler = (event) => {
        try {
          const data = JSON.parse(event.data);
          if (data.id === id) {
            ws.removeEventListener('message', handler);
            if (data.error) reject(new Error(data.error.message));
            else resolve(data.result);
          }
        } catch (err) { reject(err); }
      };
      ws.addEventListener('message', handler);
      ws.send(JSON.stringify({ id, method, params }));
    });
  }

  async function evaluate(code) {
    const res = await sendCdp('Runtime.evaluate', {
      expression: code,
      returnByValue: true,
      awaitPromise: true
    });
    return res.result.value;
  }

  await sendCdp('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false
  });

  await new Promise(r => setTimeout(r, 400));

  // =========================================================================
  // SUITE 1: 1920x1080 Canvas Lock & Zero Document Scroll
  // =========================================================================
  console.log(`${C.bold}${C.magenta}--- Suite 1: 1920x1080 Canvas Lock & Zero Document Scroll ---${C.reset}`);

  const docMetrics = await evaluate(`(() => {
    return {
      windowWidth: window.innerWidth,
      windowHeight: window.innerHeight,
      docScrollWidth: document.documentElement.scrollWidth,
      docScrollHeight: document.documentElement.scrollHeight,
      docClientWidth: document.documentElement.clientWidth,
      docClientHeight: document.documentElement.clientHeight,
      bodyScrollWidth: document.body.scrollWidth,
      bodyScrollHeight: document.body.scrollHeight,
      bodyClientWidth: document.body.clientWidth,
      bodyClientHeight: document.body.clientHeight,
      bodyOffsetWidth: document.body.offsetWidth,
      bodyOffsetHeight: document.body.offsetHeight,
      appScrollWidth: document.getElementById('app').scrollWidth,
      appScrollHeight: document.getElementById('app').scrollHeight,
      appOffsetWidth: document.getElementById('app').offsetWidth,
      appOffsetHeight: document.getElementById('app').offsetHeight,
      windowScrollX: window.scrollX,
      windowScrollY: window.scrollY
    };
  })()`);

  assert(docMetrics.windowWidth === 1920, `Window innerWidth is 1920px (observed: ${docMetrics.windowWidth})`);
  assert(docMetrics.windowHeight === 1080, `Window innerHeight is 1080px (observed: ${docMetrics.windowHeight})`);
  assert(docMetrics.docScrollWidth === 1920, `document.documentElement.scrollWidth === 1920px (observed: ${docMetrics.docScrollWidth})`);
  assert(docMetrics.docScrollHeight === 1080, `document.documentElement.scrollHeight === 1080px (observed: ${docMetrics.docScrollHeight})`);
  assert(docMetrics.bodyScrollWidth === 1920, `document.body.scrollWidth === 1920px (observed: ${docMetrics.bodyScrollWidth})`);
  assert(docMetrics.bodyScrollHeight === 1080, `document.body.scrollHeight === 1080px (observed: ${docMetrics.bodyScrollHeight})`);
  assert(docMetrics.appOffsetWidth === 1920, `app.offsetWidth === 1920px (observed: ${docMetrics.appOffsetWidth})`);
  assert(docMetrics.appOffsetHeight === 1080, `app.offsetHeight === 1080px (observed: ${docMetrics.appOffsetHeight})`);
  assert(docMetrics.appScrollWidth === 1920, `app.scrollWidth === 1920px (observed: ${docMetrics.appScrollWidth})`);
  assert(docMetrics.appScrollHeight === 1080, `app.scrollHeight === 1080px (observed: ${docMetrics.appScrollHeight})`);
  assert(docMetrics.windowScrollX === 0, `window.scrollX === 0 (observed: ${docMetrics.windowScrollX})`);
  assert(docMetrics.windowScrollY === 0, `window.scrollY === 0 (observed: ${docMetrics.windowScrollY})`);

  // Document forced scroll attempt
  const scrollAttemptResult = await evaluate(`(() => {
    window.scrollTo(500, 500);
    return { x: window.scrollX, y: window.scrollY };
  })()`);
  assert(scrollAttemptResult.x === 0 && scrollAttemptResult.y === 0, `Forced window.scrollTo(500,500) ignored by overflow:hidden lock (observed: x=${scrollAttemptResult.x}, y=${scrollAttemptResult.y})`);

  // =========================================================================
  // SUITE 2: #bgBlur Geometry, Specificity, and Coverage Inspection
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 2: #bgBlur Geometry, Specificity, & Overflow Isolation ---${C.reset}`);

  const bgBlurData = await evaluate(`(() => {
    const el = document.getElementById('bgBlur');
    if (!el) return null;
    const cs = window.getComputedStyle(el);
    const rect = el.getBoundingClientRect();
    return {
      tagName: el.tagName,
      id: el.id,
      position: cs.position,
      top: cs.top,
      left: cs.left,
      width: cs.width,
      height: cs.height,
      rectTop: rect.top,
      rectLeft: rect.left,
      rectWidth: rect.width,
      rectHeight: rect.height,
      rectRight: rect.right,
      rectBottom: rect.bottom,
      pointerEvents: cs.pointerEvents,
      zIndex: cs.zIndex,
      opacity: cs.opacity,
      filter: cs.filter || cs.webkitFilter,
      willChange: cs.willChange,
      transform: cs.transform
    };
  })()`);

  console.log(`  ${C.gray}#bgBlur computed properties:${C.reset}`, bgBlurData);

