  assert(bgBlurData.zIndex === '0', `#bgBlur z-index is 0 below views-container (observed: ${bgBlurData.zIndex})`);
  assert(bgBlurData.opacity === '0', `#bgBlur initial opacity is 0 (observed: ${bgBlurData.opacity})`);
  assert(bgBlurData.filter.includes('blur'), `#bgBlur has active blur filter (observed: ${bgBlurData.filter})`);

  // Check whether #bgBlur leaks into scroll dimensions
  const leakCheck = await evaluate(`(() => {
    const docSW = document.documentElement.scrollWidth;
    const docSH = document.documentElement.scrollHeight;
    const bodySW = document.body.scrollWidth;
    const bodySH = document.body.scrollHeight;
    return { docSW, docSH, bodySW, bodySH };
  })()`);
  assert(leakCheck.docSW === 1920, `#bgBlur does not expand document.documentElement.scrollWidth (observed: ${leakCheck.docSW})`);
  assert(leakCheck.docSH === 1080, `#bgBlur does not expand document.documentElement.scrollHeight (observed: ${leakCheck.docSH})`);
  assert(leakCheck.bodySW === 1920, `#bgBlur does not expand body.scrollWidth (observed: ${leakCheck.bodySW})`);
  assert(leakCheck.bodySH === 1080, `#bgBlur does not expand body.scrollHeight (observed: ${leakCheck.bodySH})`);

  // Stress test: what if #bgBlur width is 2040px?
  console.log(`  ${C.yellow}Testing #bgBlur extreme dimensions injection...${C.reset}`);
  const extremeBlurResult = await evaluate(`(() => {
    const el = document.getElementById('bgBlur');
    const oldStyle = el.getAttribute('style') || '';
    el.style.width = '3000px';
    el.style.height = '2000px';
    el.style.top = '-500px';
    el.style.left = '-500px';
    const res = {
      docSW: document.documentElement.scrollWidth,
      docSH: document.documentElement.scrollHeight,
      bodySW: document.body.scrollWidth,
      bodySH: document.body.scrollHeight
    };
    el.setAttribute('style', oldStyle);
    return res;
  })()`);
  assert(extremeBlurResult.docSW === 1920, `Extreme #bgBlur dimensions (3000x2000 at -500,-500) do NOT leak into document scrollWidth (observed: ${extremeBlurResult.docSW})`);
  assert(extremeBlurResult.docSH === 1080, `Extreme #bgBlur dimensions do NOT leak into document scrollHeight (observed: ${extremeBlurResult.docSH})`);

  // Inspect the specificity clash between #bgBlur and html #bgBlur
  console.log(`\n${C.yellow}  Inspecting #bgBlur dimensions and specificity interaction:${C.reset}`);
  console.log(`    Computed width: ${bgBlurData.width}`);
  console.log(`    Computed height: ${bgBlurData.height}`);
  console.log(`    BoundingRect: right=${bgBlurData.rectRight}px, bottom=${bgBlurData.rectBottom}px (top=${bgBlurData.rectTop}px, left=${bgBlurData.rectLeft}px)`);

  // =========================================================================
  // SUITE 3: .scrolled Dynamic State Transitions
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 3: .scrolled Dynamic State Transitions ---${C.reset}`);

  // Trigger .scrolled on body
  const scrolledState = await evaluate(`(() => {
    document.body.classList.add('scrolled');
    const bgBlur = document.getElementById('bgBlur');
    const shade = document.getElementById('shade');
    const header = document.getElementById('app-header');

    const csBlur = window.getComputedStyle(bgBlur);
    const csShade = window.getComputedStyle(shade);
    const csHeader = window.getComputedStyle(header);

    const res = {
      blurOpacity: csBlur.opacity,
      shadeBackground: csShade.background || csShade.backgroundColor,
      headerOpacity: csHeader.opacity,
      headerTransform: csHeader.transform,
      headerPointerEvents: csHeader.pointerEvents,
      docSW: document.documentElement.scrollWidth,
      docSH: document.documentElement.scrollHeight,
      bodySW: document.body.scrollWidth,
      bodySH: document.body.scrollHeight
    };

    document.body.classList.remove('scrolled');
    return res;
  })()`);

  assert(scrolledState.blurOpacity === '1', `.scrolled triggers #bgBlur opacity: 1 (observed: ${scrolledState.blurOpacity})`);
  assert(scrolledState.headerOpacity === '0', `.scrolled triggers .app-header opacity: 0 auto-hide (observed: ${scrolledState.headerOpacity})`);
  assert(scrolledState.headerTransform.includes('matrix'), `.scrolled triggers .app-header transform (translateY) (observed: ${scrolledState.headerTransform})`);
  assert(scrolledState.headerPointerEvents === 'none', `.scrolled disables .app-header pointer-events (observed: ${scrolledState.headerPointerEvents})`);
  assert(scrolledState.shadeBackground.includes('14, 16, 20') || scrolledState.shadeBackground.includes('rgba(14, 16, 20'), `.scrolled darkens #shade scrim (observed: ${scrolledState.shadeBackground})`);
  assert(scrolledState.docSW === 1920 && scrolledState.bodySW === 1920, `.scrolled does not alter document scrollWidth (observed: doc=${scrolledState.docSW}, body=${scrolledState.bodySW})`);

  // Test .scrolled on #app container as well
  const appScrolledState = await evaluate(`(() => {
    document.getElementById('app').classList.add('scrolled');
    const bgBlur = document.getElementById('bgBlur');
    const header = document.getElementById('app-header');
    const csBlur = window.getComputedStyle(bgBlur);
    const csHeader = window.getComputedStyle(header);
    const res = {
      blurOpacity: csBlur.opacity,
      headerOpacity: csHeader.opacity
    };
    document.getElementById('app').classList.remove('scrolled');
    return res;
  })()`);
  assert(appScrolledState.blurOpacity === '1', `#app.scrolled triggers #bgBlur opacity: 1 (observed: ${appScrolledState.blurOpacity})`);
  assert(appScrolledState.headerOpacity === '0', `#app.scrolled triggers .app-header opacity: 0 (observed: ${appScrolledState.headerOpacity})`);

  // =========================================================================
  // SUITE 4: Zero Scrollbar Expansion & Overflow Constraints
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 4: Zero Scrollbar Expansion & Overflow Constraints ---${C.reset}`);

  const overflowMetrics = await evaluate(`(() => {
    const htmlCS = window.getComputedStyle(document.documentElement);
    const bodyCS = window.getComputedStyle(document.body);
    const appCS = window.getComputedStyle(document.getElementById('app'));
    const vcCS = window.getComputedStyle(document.querySelector('.views-container'));

    return {
      htmlOverflow: htmlCS.overflow,
      htmlOverflowX: htmlCS.overflowX,
      htmlOverflowY: htmlCS.overflowY,
      bodyOverflow: bodyCS.overflow,
      bodyOverflowX: bodyCS.overflowX,
      bodyOverflowY: bodyCS.overflowY,
      bodyScrollbarWidth: bodyCS.scrollbarWidth,
      appOverflow: appCS.overflow,
      appOverflowX: appCS.overflowX,
      appOverflowY: appCS.overflowY,
      vcOverflow: vcCS.overflow
    };
  })()`);

  assert(overflowMetrics.htmlOverflow === 'hidden', `html overflow is hidden (observed: ${overflowMetrics.htmlOverflow})`);
  assert(overflowMetrics.bodyOverflow === 'hidden', `body overflow is hidden (observed: ${overflowMetrics.bodyOverflow})`);
  assert(overflowMetrics.bodyScrollbarWidth === 'none', `body scrollbar-width is none (observed: ${overflowMetrics.bodyScrollbarWidth})`);
  assert(overflowMetrics.appOverflow === 'hidden', `#app overflow is hidden (observed: ${overflowMetrics.appOverflow})`);
  assert(overflowMetrics.vcOverflow === 'hidden', `.views-container overflow is hidden (observed: ${overflowMetrics.vcOverflow})`);

  // Check all views have zero horizontal overflow
  const viewOverflows = await evaluate(`(() => {
    const views = document.querySelectorAll('.view');
    return Array.from(views).map(v => {
      const pane = v.querySelector('.view-scroll-pane');
      const cs = pane ? window.getComputedStyle(pane) : null;
      return {
        id: v.id,
        scrollPaneOverflowX: cs ? cs.overflowX : 'n/a',
        scrollPaneScrollbarWidth: cs ? cs.scrollbarWidth : 'n/a',
        scrollPaneScrollWidth: pane ? pane.scrollWidth : 0,
        scrollPaneClientWidth: pane ? pane.clientWidth : 0
      };
    });
  })()`);

  for (const vo of viewOverflows) {
    if (vo.scrollPaneOverflowX !== 'n/a') {
      assert(vo.scrollPaneOverflowX === 'hidden', `View #${vo.id} .view-scroll-pane enforces overflow-x: hidden (observed: ${vo.scrollPaneOverflowX})`);
      assert(vo.scrollPaneScrollbarWidth === 'none', `View #${vo.id} .view-scroll-pane enforces scrollbar-width: none (observed: ${vo.scrollPaneScrollbarWidth})`);
      assert(vo.scrollPaneScrollWidth <= 1920, `View #${vo.id} .view-scroll-pane scrollWidth <= 1920px (observed: ${vo.scrollPaneScrollWidth})`);
    }
  }

  // =========================================================================
  // SUITE 5: Navigation Pill Bar TV-Safe Constraints & Stacking Order
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 5: Navigation Pill Bar TV-Safe Constraints & Stacking ---${C.reset}`);

  const headerLayout = await evaluate(`(() => {
    const header = document.getElementById('app-header');
    const brand = document.getElementById('header-brand');
    const nav = document.getElementById('header-nav');
    const tabs = Array.from(document.querySelectorAll('#header-nav .nav-pill-item'));
    const hRect = header.getBoundingClientRect();
    const bRect = brand.getBoundingClientRect();
    const nRect = nav.getBoundingClientRect();

    const bg = document.getElementById('bg');
    const bgBlur = document.getElementById('bgBlur');
    const shade = document.getElementById('shade');
    const vc = document.querySelector('.views-container');

    return {
      headerRect: { top: hRect.top, left: hRect.left, right: hRect.right, height: hRect.height },
      brandRect: { left: bRect.left, right: bRect.right },
      navRect: { left: nRect.left, right: nRect.right },
      tabCount: tabs.length,
      tabs: tabs.map(t => ({ id: t.id, route: t.getAttribute('data-route'), rect: t.getBoundingClientRect() })),
      zIndices: {
        bg: window.getComputedStyle(bg).zIndex,
        bgBlur: window.getComputedStyle(bgBlur).zIndex,
        shade: window.getComputedStyle(shade).zIndex,
        viewsContainer: window.getComputedStyle(vc).zIndex,
        header: window.getComputedStyle(header).zIndex
      },
      pointerEvents: {
        bg: window.getComputedStyle(bg).pointerEvents,
        bgBlur: window.getComputedStyle(bgBlur).pointerEvents,
        shade: window.getComputedStyle(shade).pointerEvents
      }
    };
  })()`);

  assert(headerLayout.headerRect.left === 0 && headerLayout.headerRect.right === 1920, `Header spans 0 to 1920px (observed: ${headerLayout.headerRect.left} to ${headerLayout.headerRect.right})`);
  assert(headerLayout.brandRect.left >= 96, `Brand logomark aligns with 96px TV safe margin (observed: ${headerLayout.brandRect.left}px >= 96px)`);
  assert(headerLayout.navRect.right <= 1824, `Navigation pill bar stays within 1824px TV safe margin (observed: ${headerLayout.navRect.right}px <= 1824px)`);
  assert(headerLayout.tabCount === 4, `Header nav contains 4 pill tabs (Home, Movies, Series, Search) (found: ${headerLayout.tabCount})`);

  // Stacking order: bg (0) == bgBlur (0) < shade (1) < views (2) < header (100)
  assert(parseInt(headerLayout.zIndices.bg) <= parseInt(headerLayout.zIndices.shade), `Stacking order: #bg (z:${headerLayout.zIndices.bg}) <= #shade (z:${headerLayout.zIndices.shade})`);
  assert(parseInt(headerLayout.zIndices.shade) < parseInt(headerLayout.zIndices.viewsContainer), `Stacking order: #shade (z:${headerLayout.zIndices.shade}) < .views-container (z:${headerLayout.zIndices.viewsContainer})`);
  assert(parseInt(headerLayout.zIndices.viewsContainer) < parseInt(headerLayout.zIndices.header), `Stacking order: .views-container (z:${headerLayout.zIndices.viewsContainer}) < .app-header (z:${headerLayout.zIndices.header})`);

  assert(headerLayout.pointerEvents.bg === 'none', `#bg pointer-events is none`);
  assert(headerLayout.pointerEvents.bgBlur === 'none', `#bgBlur pointer-events is none`);
  assert(headerLayout.pointerEvents.shade === 'none', `#shade pointer-events is none`);

  // =========================================================================
  // SUITE 6: Viewport Resize & Abnormal Display Mode Stress
  // =========================================================================
  console.log(`\n${C.bold}${C.magenta}--- Suite 6: Viewport Resize & Abnormal Display Mode Stress ---${C.reset}`);

  const stressViewports = [
    { name: '720p HD', w: 1280, h: 720 },
    { name: '1440p QHD', w: 2560, h: 1440 },
    { name: '4K UHD', w: 3840, h: 2160 },
    { name: '16:10 Laptop (1920x1200)', w: 1920, h: 1200 },
    { name: 'Narrow TV (1366x768)', w: 1366, h: 768 }
  ];

  for (const vp of stressViewports) {
    await sendCdp('Emulation.setDeviceMetricsOverride', {
      width: vp.w,
      height: vp.h,
      deviceScaleFactor: 1,
      mobile: false
    });

    const res = await evaluate(`(() => {
      const app = document.getElementById('app');
      return {
        appW: app.offsetWidth,
        appH: app.offsetHeight
      };
    })()`);

    assert(res.appW === 1920, `[${vp.name}] #app maintains strict 1920px width (observed: ${res.appW}px)`);
    assert(res.appH === 1080, `[${vp.name}] #app maintains strict 1080px height (observed: ${res.appH}px)`);
  }

  // Restore 1080p
  await sendCdp('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false
  });

  // =========================================================================
  // SUMMARY
  // =========================================================================
  console.log(`\n${C.bold}${C.cyan}===============================================================${C.reset}`);
  console.log(`${C.bold}UI-M1 Stress Test Execution Summary:${C.reset}`);
  console.log(`  Total Checks:  ${totalTests}`);
  console.log(`  Passed Checks: ${C.green}${passedTests}${C.reset}`);
  console.log(`  Failed Checks: ${failedTests > 0 ? C.red + failedTests + C.reset : '0'}`);
  console.log(`${C.bold}${C.cyan}===============================================================${C.reset}\n`);

  if (failedTests === 0) {
    console.log(`${C.bold}${C.green}VERDICT: APPROVE (100% of UI-M1 adversarial stress checks passed)${C.reset}\n`);
    process.exit(0);
  } else {
    console.log(`${C.bold}${C.red}VERDICT: REJECT (${failedTests} stress checks failed)${C.reset}\n`);
    process.exit(1);
  }
}

run().catch(err => {
  console.error('Test execution error:', err);
  process.exit(1);
});

