// =========================================================================
// SUITE 3: .scrolled Dynamic State Transitions
// =========================================================================
console.log(`\n${C.bold}${C.magenta}--- Suite 3: .scrolled Dynamic State Transitions ---${C.reset}`);

// Trigger .scrolled on body and wait for CSS transitions (0.35s / 0.4s) to settle
await evaluate(`document.body.classList.add('scrolled')`);
await new Promise(r => setTimeout(r, 500));

const scrolledState = await evaluate(`(() => {
  const bgBlur = document.getElementById('bgBlur');
  const shade = document.getElementById('shade');
  const header = document.getElementById('app-header');

  const csBlur = window.getComputedStyle(bgBlur);
  const csShade = window.getComputedStyle(shade);
  const csHeader = window.getComputedStyle(header);

  return {
    blurOpacity: csBlur.opacity,
    shadeBgColor: csShade.backgroundColor,
    shadeBgImage: csShade.backgroundImage,
    headerOpacity: csHeader.opacity,
    headerTransform: csHeader.transform,
    headerPointerEvents: csHeader.pointerEvents,
    docSW: document.documentElement.scrollWidth,
    docSH: document.documentElement.scrollHeight,
    bodySW: document.body.scrollWidth,
    bodySH: document.body.scrollHeight
  };
})()`);

// Remove .scrolled and wait for restoration
await evaluate(`document.body.classList.remove('scrolled')`);
await new Promise(r => setTimeout(r, 500));

const restoredState = await evaluate(`(() => {
  const bgBlur = document.getElementById('bgBlur');
  const header = document.getElementById('app-header');
  return {
    blurOpacity: window.getComputedStyle(bgBlur).opacity,
    headerOpacity: window.getComputedStyle(header).opacity,
    headerPointerEvents: window.getComputedStyle(header).pointerEvents
  };
})()`);

assert(parseFloat(scrolledState.blurOpacity) >= 0.95, `.scrolled triggers #bgBlur opacity -> 1 (observed: ${scrolledState.blurOpacity})`);
assert(parseFloat(scrolledState.headerOpacity) <= 0.05, `.scrolled triggers .app-header opacity -> 0 auto-hide (observed: ${scrolledState.headerOpacity})`);
assert(scrolledState.headerTransform.includes('matrix'), `.scrolled triggers .app-header transform (translateY) (observed: ${scrolledState.headerTransform})`);
assert(scrolledState.headerPointerEvents === 'none', `.scrolled disables .app-header pointer-events (observed: ${scrolledState.headerPointerEvents})`);
assert(scrolledState.shadeBgColor.includes('14, 16, 20') || scrolledState.shadeBgColor.includes('14,16,20'), `.scrolled darkens #shade scrim background-color (observed: ${scrolledState.shadeBgColor})`);
assert(scrolledState.docSW === 1920 && scrolledState.bodySW === 1920, `.scrolled does not alter document scrollWidth (observed: doc=${scrolledState.docSW}, body=${scrolledState.bodySW})`);

// Restored state checks
assert(parseFloat(restoredState.blurOpacity) <= 0.05, `Removing .scrolled restores #bgBlur opacity -> 0 (observed: ${restoredState.blurOpacity})`);
assert(parseFloat(restoredState.headerOpacity) >= 0.95, `Removing .scrolled restores .app-header opacity -> 1 (observed: ${restoredState.headerOpacity})`);
assert(restoredState.headerPointerEvents === 'auto', `Removing .scrolled restores .app-header pointer-events: auto (observed: ${restoredState.headerPointerEvents})`);

// Test .scrolled on #app container as well
await evaluate(`document.getElementById('app').classList.add('scrolled')`);
await new Promise(r => setTimeout(r, 500));
const appScrolledState = await evaluate(`(() => {
  const bgBlur = document.getElementById('bgBlur');
  const header = document.getElementById('app-header');
  return {
    blurOpacity: window.getComputedStyle(bgBlur).opacity,
    headerOpacity: window.getComputedStyle(header).opacity
  };
})()`);
await evaluate(`document.getElementById('app').classList.remove('scrolled')`);
await new Promise(r => setTimeout(r, 500));

assert(parseFloat(appScrolledState.blurOpacity) >= 0.95, `#app.scrolled triggers #bgBlur opacity -> 1 (observed: ${appScrolledState.blurOpacity})`);
assert(parseFloat(appScrolledState.headerOpacity) <= 0.05, `#app.scrolled triggers .app-header opacity -> 0 (observed: ${appScrolledState.headerOpacity})`);

